1	/** Flat fee added to every premium, regardless of the items insured. */
2	const PROCESSING_FEE = 5;
3	
4	export type Scenario = {
5	  customer: { yearsWithMHPCO: number };
6	  steps: Step[];
7	};
8	
9	export type Step = {
10	  op: string;
11	  items: Item[];
12	};
13	
14	export type Item = Record<string, unknown>;
15	
16	export type Result = { premium: number };
17	
18	export type ScenarioOutcome = { results: Result[] };
19	
20	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
21	  const items = scenario.steps[0].items;
22	  const policyBase = items.length * 100;
23	  const firstInsurance = policyBase * 0.1;
24	  return { results: [{ premium: policyBase + firstInsurance + PROCESSING_FEE }] };
25	};
